function showDialog(title,body,footer=''){const d=$('#dialog');if(!d.open)opener=document.activeElement;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><span class="grow"></span><button class="quiet" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();const focus=d.querySelector('[autofocus]')||d.querySelector('button');focus?.focus()}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();if(opener?.isConnected)opener.focus();else $('#main').focus()}
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
$('#dialog').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=$$('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex]:not([tabindex="-1"])',$('#dialog')).filter(x=>x.getClientRects().length);if(!items.length){e.preventDefault();return}const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
